"""A small spreadsheet formula engine.

Supports:
- Plain values (numbers, strings) via set_cell
- Formulas starting with '=' : numbers, cell refs (up to column ZZ),
  + - * / with precedence and parentheses, SUM(range), AVG(range)
- Dependency-driven evaluation in topological order
- Cycle detection: every cell in a cycle becomes '#CYCLE!'
- Parse errors yield '#PARSE!'
"""

import re


def col_to_num(letters):
    """'A' -> 1, 'Z' -> 26, 'AA' -> 27, 'ZZ' -> 702."""
    n = 0
    for ch in letters.upper():
        if not ('A' <= ch <= 'Z'):
            raise ValueError("bad column: %r" % letters)
        n = n * 26 + (ord(ch) - ord('A') + 1)
    if n > 26 * 27:  # beyond ZZ
        raise ValueError("column out of range: %r" % letters)
    return n


def num_to_col(n):
    """1 -> 'A', 26 -> 'Z', 27 -> 'AA'."""
    s = ""
    while n > 0:
        n, r = divmod(n - 1, 26)
        s = chr(ord('A') + r) + s
    return s


_CELL_RE = re.compile(r'^([A-Za-z]{1,2})([0-9]+)$')


def parse_addr(addr):
    """'AA1' -> ('AA', 1). Raises ValueError on bad addresses."""
    m = _CELL_RE.match(addr.strip())
    if not m:
        raise ValueError("bad cell address: %r" % addr)
    letters = m.group(1).upper()
    row = int(m.group(2))
    if row < 1:
        raise ValueError("bad row in %r" % addr)
    col_to_num(letters)  # validates range (<= ZZ)
    return letters, row


# ---------------------------------------------------------------------------
# Formula parsing (recursive descent)
#
# AST nodes:
#   ('num', value)
#   ('ref', 'A1')
#   ('range', addr1, addr2)
#   ('bin', op, left, right)
#   ('neg', operand)
#   ('call', NAME, arg_node)
# ---------------------------------------------------------------------------

_TOKEN_RE = re.compile(r"""
    \s*(?:
      (?P<num>\d+(?:\.\d+)?)
    | (?P<cell>[A-Za-z]{1,2}\d+)
    | (?P<ident>[A-Za-z]+)
    | (?P<op>[-+*/():])
    )""", re.VERBOSE)


class _Parser:
    def __init__(self, text):
        self.tokens = []
        pos = 0
        while pos < len(text):
            m = _TOKEN_RE.match(text, pos)
            if not m or m.end() == pos:
                rest = text[pos:].strip()
                if not rest:
                    break
                raise SyntaxError("unexpected token near %r" % rest[:10])
            pos = m.end()
            if m.group('num') is not None:
                v = m.group('num')
                self.tokens.append(('num', float(v) if '.' in v else int(v)))
            elif m.group('cell') is not None:
                self.tokens.append(('cell', m.group('cell').upper()))
            elif m.group('ident') is not None:
                self.tokens.append(('ident', m.group('ident').upper()))
            else:
                self.tokens.append(('op', m.group('op')))
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None)

    def next(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect_op(self, op):
        kind, val = self.next()
        if kind != 'op' or val != op:
            raise SyntaxError("expected %r" % op)

    def parse(self):
        node = self.expr()
        if self.i != len(self.tokens):
            raise SyntaxError("trailing input")
        return node

    def expr(self):
        node = self.term()
        while True:
            kind, val = self.peek()
            if kind == 'op' and val in '+-':
                self.next()
                node = ('bin', val, node, self.term())
            else:
                return node

    def term(self):
        node = self.factor()
        while True:
            kind, val = self.peek()
            if kind == 'op' and val in '*/':
                self.next()
                node = ('bin', val, node, self.factor())
            else:
                return node

    def factor(self):
        kind, val = self.next()
        if kind == 'num':
            return ('num', val)
        if kind == 'cell':
            nk, nv = self.peek()
            if nk == 'op' and nv == ':':
                self.next()
                k2, v2 = self.next()
                if k2 != 'cell':
                    raise SyntaxError("expected cell after ':'")
                return ('range', self._addr(val), self._addr(v2))
            return ('ref', self._addr(val))
        if kind == 'ident':
            if val in ('SUM', 'AVG'):
                self.expect_op('(')
                arg = self.expr()
                self.expect_op(')')
                return ('call', val, arg)
            raise SyntaxError("unknown function %r" % val)
        if kind == 'op' and val == '(':
            node = self.expr()
            self.expect_op(')')
            return node
        if kind == 'op' and val == '-':
            return ('neg', self.factor())
        if kind == 'op' and val == '+':  # unary plus
            return self.factor()
        raise SyntaxError("unexpected token %r" % (val,))

    @staticmethod
    def _addr(cell):
        try:
            parse_addr(cell)
        except ValueError:
            raise SyntaxError("bad cell reference %r" % cell)
        return cell.upper()


def parse_formula(text):
    """Parse formula body (without '='). Raises SyntaxError."""
    return _Parser(text).parse()


