# The Sheet
# ---------------------------------------------------------------------------

CYCLE_ERROR = '#CYCLE!'
PARSE_ERROR = '#PARSE!'
DIV0_ERROR = '#DIV/0!'


def _is_error(v):
    return isinstance(v, str) and v.startswith('#')


def _iter_range(a1, a2):
    l1, r1 = parse_addr(a1)
    l2, r2 = parse_addr(a2)
    c1, c2 = sorted((col_to_num(l1), col_to_num(l2)))
    r_lo, r_hi = sorted((r1, r2))
    for c in range(c1, c2 + 1):
        for r in range(r_lo, r_hi + 1):
            yield "%s%d" % (num_to_col(c), r)


class Sheet:
    def __init__(self):
        self._raw = {}     # addr -> raw content assigned by user
        self._ast = {}     # addr -> AST tuple for formulas, or PARSE_ERROR
        self._values = {}  # addr -> computed value
        self._dirty = True

    # -- public API ---------------------------------------------------------

    def set_cell(self, addr, content):
        addr = self._norm(addr)
        self._raw[addr] = content
        if isinstance(content, str) and content.startswith('='):
            try:
                self._ast[addr] = parse_formula(content[1:])
            except SyntaxError:
                self._ast[addr] = PARSE_ERROR
        else:
            self._ast.pop(addr, None)
            self._values[addr] = content
        self._dirty = True

    def get(self, addr):
        addr = self._norm(addr)
        if addr not in self._raw:
            return None
        if self._dirty:
            self._recompute()
            self._dirty = False
        return self._values.get(addr)

    # -- internals ----------------------------------------------------------

    @staticmethod
    def _norm(addr):
        letters, row = parse_addr(addr)
        return "%s%d" % (letters, row)

    def _deps(self, addr):
        """Set of cell addresses this formula cell depends on."""
        deps = set()

        def walk(node):
            t = node[0]
            if t == 'ref':
                deps.add(node[1])
            elif t == 'range':
                deps.update(_iter_range(node[1], node[2]))
            elif t == 'bin':
                walk(node[2]); walk(node[3])
            elif t == 'neg':
                walk(node[1])
            elif t == 'call':
                walk(node[2])

        ast = self._ast.get(addr)
        if ast is not None and not isinstance(ast, str):
            walk(ast)
        return deps

    def _recompute(self):
        # Build dependency graph among formula cells.
        formula_cells = [a for a in self._raw if a in self._ast]
        deps = {a: self._deps(a) for a in formula_cells}
        dependents = {a: set() for a in formula_cells}
        for a, ds in deps.items():
            for d in ds:
                if d in dependents:
                    dependents[d].add(a)

        # Tarjan's SCC (iterative) over edges cell -> its dependencies.
        index = {}
        lowlink = {}
        on_stack = set()
        stack = []
        counter = [0]
        sccs = []  # emitted in reverse topological order (deps first)

        for root in formula_cells:
            if root in index:
                continue
            work = [(root, iter(sorted(deps[root])))]
            index[root] = lowlink[root] = counter[0]
            counter[0] += 1
            stack.append(root)
            on_stack.add(root)
            while work:
                node, it = work[-1]
                advanced = False
                for dep in it:
                    if dep not in deps:
                        continue  # not a formula cell: leaf
                    if dep not in index:
                        index[dep] = lowlink[dep] = counter[0]
                        counter[0] += 1
                        stack.append(dep)
                        on_stack.add(dep)
                        work.append((dep, iter(sorted(deps[dep]))))
                        advanced = True
                        break
                    elif dep in on_stack:
                        lowlink[node] = min(lowlink[node], index[dep])
                if advanced:
                    continue
                work.pop()
                if work:
                    parent = work[-1][0]
                    lowlink[parent] = min(lowlink[parent], lowlink[node])
                if lowlink[node] == index[node]:
                    scc = []
                    while True:
                        w = stack.pop()
                        on_stack.discard(w)
                        scc.append(w)
                        if w == node:
                            break
                    sccs.append(scc)

        # Evaluate SCCs in order (dependencies before dependents).
        for scc in sccs:
            if len(scc) > 1 or scc[0] in deps[scc[0]]:
                # Cycle: every member gets the error value.
                for a in scc:
                    self._values[a] = CYCLE_ERROR
                continue
            addr = scc[0]
            ast = self._ast[addr]
            self._values[addr] = (
                PARSE_ERROR if isinstance(ast, str) else self._eval(ast)
            )

    def _lookup(self, addr):
        v = self._values.get(addr)
        if v is None and addr not in self._raw:
            return 0  # empty cell counts as 0
        return v

    def _eval(self, node):
        t = node[0]
        if t == 'num':
            return node[1]
        if t == 'ref':
            v = self._lookup(node[1])
            return v
        if t == 'neg':
            v = self._eval(node[1])
            if _is_error(v):
                return v
            if not isinstance(v, (int, float)):
                return PARSE_ERROR
            return -v
        if t == 'bin':
            op = node[1]
            left = self._eval(node[2])
            if _is_error(left):
                return left
            right = self._eval(node[3])
            if _is_error(right):
                return right
            if not (isinstance(left, (int, float)) and isinstance(right, (int, float))):
                return PARSE_ERROR
            if op == '+':
                return left + right
            if op == '-':
                return left - right
            if op == '*':
                return left * right
            if op == '/':
                if right == 0:
                    return DIV0_ERROR
                return left / right
            raise ValueError("bad operator %r" % op)
        if t == 'call':
            fname, arg = node[1], node[2]
            if arg[0] != 'range':
                return PARSE_ERROR
            nums = []
            for cell in _iter_range(arg[1], arg[2]):
                v = self._values.get(cell)
                if v is None or not isinstance(v, (int, float)):
                    continue  # empty / non-numeric: ignored
                nums.append(float(v))
            if fname == 'SUM':
                total = 0
                acc = 0
                for v in nums:
                    acc += v
                # preserve int-ness when exact
                if all(float(v).is_integer() for v in nums):
                    return int(acc)
                return acc
            if fname == 'AVG':
                if not nums:
                    return DIV0_ERROR
                avg = sum(nums) / len(nums)
                return int(avg) if avg.is_integer() else avg
            return PARSE_ERROR
        raise ValueError("bad node %r" % (node,))

